#!/usr/bin/env node
/** Independent comparison of actual native reports with the executable TS corpus.
 * No report is generated by this script. Imported issued content is always exact;
 * a fresh native issue may use different JSON whitespace/number spelling once,
 * then its native content string must remain byte-for-byte unchanged thereafter.
 */
import { createHash } from 'node:crypto';
import { readFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { isDeepStrictEqual } from 'node:util';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');

function requireValue(condition, message) {
  if (!condition) throw new Error(message);
}

function object(value) { return value !== null && typeof value === 'object' && !Array.isArray(value); }

function parse(value, context) {
  requireValue(typeof value === 'string', `${context}: missing JSON string`);
  try { return JSON.parse(value); } catch { throw new Error(`${context}: invalid JSON`); }
}

function difference(actual, expected, path = '$') {
  if (Object.is(actual, expected)) return path;
  if (Array.isArray(actual) && Array.isArray(expected)) {
    if (actual.length !== expected.length) return `${path}.length`;
    for (let i = 0; i < expected.length; i++)
      if (!isDeepStrictEqual(actual[i], expected[i])) return difference(actual[i], expected[i], `${path}[${i}]`);
  } else if (object(actual) && object(expected)) {
    const keys = [...new Set([...Object.keys(expected), ...Object.keys(actual)])].sort();
    for (const key of keys) {
      const next = `${path}[${JSON.stringify(key)}]`;
      if (!Object.hasOwn(actual, key) || !Object.hasOwn(expected, key)) return next;
      if (!isDeepStrictEqual(actual[key], expected[key])) return difference(actual[key], expected[key], next);
    }
  }
  return path;
}

function equal(actual, expected, context) {
  if (!isDeepStrictEqual(actual, expected)) throw new Error(`${context}: semantic mismatch at ${difference(actual, expected)}`);
}

function ordered(actual, expected, context, seen) {
  requireValue(Array.isArray(actual) && actual.length === expected.length, `${context}: missing or extra results`);
  for (let i = 0; i < expected.length; i++) {
    requireValue(object(actual[i]) && typeof actual[i].id === 'string', `${context}[${i}]: malformed result`);
    requireValue(!seen.has(actual[i].id), `${context}: duplicate result ${actual[i].id}`);
    seen.add(actual[i].id);
    requireValue(actual[i].id === expected[i].id, `${context}[${i}]: reordered or unexpected result ID`);
  }
}

function workspace(source, context) {
  const value = parse(source, context);
  requireValue(object(value), `${context}: expected source object`);
  if (!Object.hasOwn(value, 'format') && Object.hasOwn(value, 'schemaVersion'))
    return { format: 'spatial-previs-workspace', version: 1, project: value,
      acceptedKeys: [], undo: [], redo: [], checks: [], reviews: [], issued: [] };
  return value;
}

function artifacts(state, context) {
  requireValue(object(state) && Array.isArray(state.issued), `${context}: missing issued collection`);
  const result = new Map();
  for (const artifact of state.issued) {
    requireValue(object(artifact) && typeof artifact.id === 'string' && typeof artifact.content === 'string',
      `${context}: malformed issued artifact`);
    requireValue(!result.has(artifact.id), `${context}: duplicate issued artifact ${artifact.id}`);
    result.set(artifact.id, artifact);
  }
  return result;
}

function importedBaseline(state, context) {
  return new Map([...artifacts(state, context)].map(([id, artifact]) =>
    [id, { native: artifact.content, reference: artifact.content }]));
}

function compareIssued(actual, expected, baseline, allowNewIssue, context) {
  const actualArtifacts = artifacts(actual, context);
  const expectedArtifacts = artifacts(expected, `${context}: reference`);
  for (const id of baseline.keys()) {
    requireValue(actualArtifacts.has(id), `${context}: dropped immutable artifact ${id}`);
    requireValue(expectedArtifacts.has(id), `${context}: reference dropped immutable artifact ${id}`);
  }
  let created = 0;
  for (const [id, artifact] of actualArtifacts) {
    const reference = expectedArtifacts.get(id);
    requireValue(reference, `${context}: unexpected issued artifact ${id}`);
    if (!baseline.has(id)) {
      requireValue(allowNewIssue, `${context}: artifact appeared outside successful issue ${id}`);
      equal(parse(artifact.content, `${context}: new native content`),
        parse(reference.content, `${context}: new reference content`), `${context}: new issue ${id}`);
      baseline.set(id, { native: artifact.content, reference: reference.content });
      created++;
    }
    const original = baseline.get(id);
    requireValue(artifact.content === original.native, `${context}: immutable issued bytes changed for ${id}`);
    requireValue(reference.content === original.reference, `${context}: reference issued bytes changed for ${id}`);
  }
  if (allowNewIssue) requireValue(created === 1, `${context}: successful issue did not create exactly one artifact`);
  const normalized = structuredClone(actual);
  for (const artifact of normalized.issued) artifact.content = baseline.get(artifact.id).reference;
  return normalized;
}

export function compareWorkspaceReport(corpus, report) {
  requireValue(object(corpus) && corpus.format === 'spatial-previs-workspace-conformance'
    && corpus.version === 1 && corpus.authorization === 'fixture-principals-v1'
    && Array.isArray(corpus.parseCases) && corpus.parseCases.length > 0
    && Array.isArray(corpus.hashCases) && corpus.hashCases.length > 0
    && Array.isArray(corpus.scenarios) && corpus.scenarios.length > 0, 'Unsupported workspace corpus');
  requireValue(object(report) && report.format === 'spatial-previs-native-workspace-conformance'
    && report.version === 1 && report.failures === 0
    && typeof report.engineVersion === 'string' && report.engineVersion.trim().length > 0,
  'Incomplete, failed, or unsupported native workspace report');
  const seen = new Set();
  ordered(report.parseCases, corpus.parseCases, 'parseCases', seen);
  for (let i = 0; i < corpus.parseCases.length; i++) {
    const expected = corpus.parseCases[i], actual = report.parseCases[i], context = expected.id;
    requireValue(actual.accepted === expected.valid && actual.passed === true
      && actual.unchangedOnRejection === true, `${context}: native parse acceptance/state-preservation failure`);
    if (expected.valid) equal(parse(actual.workspaceJson, context), parse(expected.expectedJson, `${context}: reference`), context);
    else requireValue(!Object.hasOwn(actual, 'workspaceJson'), `${context}: rejected import returned replacement data`);
  }

  ordered(report.hashCases, corpus.hashCases, 'hashCases', seen);
  for (let i = 0; i < corpus.hashCases.length; i++) {
    const expected = corpus.hashCases[i], actual = report.hashCases[i], context = expected.id;
    requireValue(actual.accepted === true && actual.passed === true, `${context}: native hash calculation failed`);
    requireValue(typeof actual.hash === 'string' && /^[a-f0-9]{64}$/.test(actual.hash)
      && actual.hash === expected.expectedHash, `${context}: SHA-256 mismatch`);
    requireValue(typeof actual.canonical === 'string' && actual.canonical === expected.expectedCanonical,
      `${context}: canonical JSON mismatch`);
    requireValue(createHash('sha256').update(actual.canonical, 'utf8').digest('hex') === actual.hash,
      `${context}: digest does not match reported canonical UTF-8 input`);
  }

  ordered(report.scenarios, corpus.scenarios, 'scenarios', seen);
  let steps = 0;
  for (let i = 0; i < corpus.scenarios.length; i++) {
    const expectedScenario = corpus.scenarios[i], actualScenario = report.scenarios[i];
    requireValue(actualScenario.initialized === true, `${expectedScenario.id}: native initialization failed`);
    ordered(actualScenario.steps, expectedScenario.steps, `${expectedScenario.id}.steps`, seen);
    let previousNative = workspace(expectedScenario.initialJson, `${expectedScenario.id}: initial source`);
    let baseline = importedBaseline(previousNative, `${expectedScenario.id}: initial issued bytes`);
    for (let j = 0; j < expectedScenario.steps.length; j++) {
      steps++;
      const expected = expectedScenario.steps[j], actual = actualScenario.steps[j], context = expected.id;
      requireValue(actual.accepted === expected.expectedAccepted && actual.passed === true
        && actual.unchangedOnRejection === true && actual.issuedBytesPreserved === true,
      `${context}: native action acceptance/preservation failure`);
      const state = parse(actual.stateJson, `${context}: state`);
      const expectedState = parse(expected.expectedStateJson, `${context}: reference state`);
      let result = parse(actual.resultJson, `${context}: result`);
      const expectedResult = parse(expected.expectedResultJson, `${context}: reference result`);
      if (!actual.accepted) {
        equal(state, previousNative, `${context}: rejected action changed native state`);
        requireValue(result === null, `${context}: rejected action returned a result`);
      }
      if (expected.action === 'import' && actual.accepted) {
        const input = parse(expected.json, `${context}: import input`);
        baseline = importedBaseline(workspace(input.json, `${context}: imported source`), `${context}: imported issued bytes`);
      }
      const newIssue = expected.action === 'issue' && actual.accepted;
      const normalized = compareIssued(state, expectedState, baseline, newIssue, context);
      equal(normalized, expectedState, `${context}: workspace state`);
      if (newIssue) {
        requireValue(object(result) && object(expectedResult) && result.id === expectedResult.id && baseline.has(result.id),
          `${context}: malformed issue result`);
        const original = baseline.get(result.id);
        requireValue(result.content === original.native && expectedResult.content === original.reference,
          `${context}: issue result content differs from stored artifact`);
        result = { ...result, content: original.reference };
      }
      equal(result, expectedResult, `${context}: action result`);
      previousNative = state;
    }
  }
  return { parseCases: corpus.parseCases.length, hashCases: corpus.hashCases.length, scenarios: corpus.scenarios.length, steps };
}

if (process.argv[1] && import.meta.url === pathToFileURL(resolve(process.argv[1])).href) {
  const reportPath = process.argv[2];
  if (!reportPath) throw new Error('Usage: node scripts/compare-r0-native-workspace.mjs <native-workspace-report.json>');
  const corpus = JSON.parse(readFileSync(resolve(root, 'tests/fixtures/r0/workspace-conformance.v1.json'), 'utf8'));
  const report = JSON.parse(readFileSync(reportPath, 'utf8'));
  const counts = compareWorkspaceReport(corpus, report);
  console.log(`PASS ${counts.parseCases} native workspace parse cases and ${counts.hashCases} canonical SHA-256 cases (${report.engineVersion})`);
  console.log(`PASS ${counts.scenarios} native scenarios / ${counts.steps} ordered steps, results and issued-byte preservation`);
  console.log('Engine rendering, actual device interaction and owner acceptance remain separate gates.');
}
